function oly_admin():void{if(!olympia_admin()){http_response_code(403);exit('Chỉ quản trị được thực hiện thao tác này.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
 $a=(string)($_POST['action']??'');$wid=trim((string)($_POST['week_id']??''));
 try{
  if($a==='save_week'){oly_admin();$id=$wid?:olympia_uid('ow');$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Vui lòng nhập tên tuần.');$mode=in_array($_POST['access_mode']??'',['auto','open','locked'],true)?$_POST['access_mode']:'auto';$open=str_replace('T',' ',trim((string)($_POST['open_at']??'')))?:null;$close=str_replace('T',' ',trim((string)($_POST['close_at']??'')))?:null;$db=olympia_db();$s=$db->prepare('INSERT INTO cds_olympia_weeks(id,title,week_label,open_at,close_at,access_mode,created_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE title=VALUES(title),week_label=VALUES(week_label),open_at=VALUES(open_at),close_at=VALUES(close_at),access_mode=VALUES(access_mode)');$s->execute([$id,$title,trim((string)($_POST['week_label']??'')),$open,$close,$mode,(string)($user['id']??'')]);$db->prepare('DELETE FROM cds_olympia_week_classes WHERE week_id=?')->execute([$id]);$ins=$db->prepare('INSERT INTO cds_olympia_week_classes(week_id,class_id,class_name) VALUES(?,?,?)');$map=olympia_class_map();foreach((array)($_POST['class_ids']??[]) as $cid)if(isset($map[$cid]))$ins->execute([$id,$cid,(string)$map[$cid]['name']]);flash('Đã lưu tuần và phạm vi lớp.','success');oly_go('manage',$id);
  }
  if($a==='delete_week'){oly_admin();olympia_db()->prepare('DELETE FROM cds_olympia_weeks WHERE id=?')->execute([$wid]);flash('Đã xóa tuần Olympia.','warning');oly_go('manage');}
  if($a==='save_question'){oly_admin();$id=trim((string)($_POST['question_id']??''))?:olympia_uid('oq');$q=trim((string)($_POST['question_text']??''));if(!$wid||$q==='')throw new RuntimeException('Thiếu tuần hoặc nội dung câu hỏi.');$s=olympia_db()->prepare('INSERT INTO cds_olympia_questions(id,week_id,stage_name,question_text,answer_text,points,sort_order) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE stage_name=VALUES(stage_name),question_text=VALUES(question_text),answer_text=VALUES(answer_text),points=VALUES(points),sort_order=VALUES(sort_order)');$s->execute([$id,$wid,trim((string)($_POST['stage_name']??'Khởi động')), $q,trim((string)($_POST['answer_text']??'')),max(0,(int)($_POST['points']??10)),max(0,(int)($_POST['sort_order']??0))]);flash('Đã lưu câu hỏi.','success');oly_go('manage',$wid);}
  if($a==='import_questions'){oly_admin();$lines=preg_split('/\R/u',trim((string)($_POST['bulk']??'')));$next=(int)olympia_db()->query("SELECT COALESCE(MAX(sort_order),0)+1 FROM cds_olympia_questions WHERE week_id=".olympia_db()->quote($wid))->fetchColumn();$s=olympia_db()->prepare('INSERT INTO cds_olympia_questions(id,week_id,stage_name,question_text,answer_text,points,sort_order) VALUES(?,?,?,?,?,?,?)');$n=0;foreach($lines as $line){$line=trim($line);if($line===''||str_starts_with($line,'#'))continue;$p=array_map('trim',str_getcsv($line,'|'));if(count($p)<2||$p[1]==='')continue;$s->execute([olympia_uid('oq'),$wid,$p[0]?:'Khởi động',$p[1],$p[2]??'',max(0,(int)($p[3]??10)),$next++]);$n++;}flash('Đã nạp '.$n.' câu hỏi.','success');oly_go('manage',$wid);}
  if($a==='delete_question'){oly_admin();olympia_db()->prepare('DELETE FROM cds_olympia_questions WHERE id=?')->execute([$_POST['question_id']??'']);flash('Đã xóa câu hỏi.','warning');oly_go('manage',$wid);}
  if($a==='save_assets'){oly_admin();$fields=['game_icon'=>'image','welcome_logo'=>'image','music_welcome'=>'audio','music_khoi_dong'=>'audio','music_vuot_chuong_ngai_vat'=>'audio','music_tang_toc'=>'audio','music_ve_dich'=>'audio','music_question'=>'audio','sound_end'=>'audio','sound_score'=>'audio'];foreach($fields as $key=>$kind){if(!empty($_POST['clear_'.$key])){olympia_save_setting($key,'');continue;}$path=olympia_upload_asset($key,$kind);if($path!=='')olympia_save_setting($key,$path);}flash('Đã cập nhật logo và âm thanh Olympia.','success');oly_go('manage',$wid);}
  if($a==='save_marks'){oly_admin();$w=olympia_week($wid);$cid=trim((string)($_POST['class_id']??''));$qid=trim((string)($_POST['question_id']??''));if(!$w||!olympia_is_open($w)||!olympia_can_class($cid))throw new RuntimeException('Tuần chưa mở hoặc bạn không phụ trách lớp này.');if(!in_array($cid,olympia_week_class_ids($wid),true))throw new RuntimeException('Tuần này chưa được gán cho lớp.');$students=[];foreach(olympia_students($cid) as $s)$students[(string)$s['id']]=$s;$db=olympia_db();$db->beginTransaction();$db->prepare('DELETE FROM cds_olympia_scores WHERE question_id=? AND class_id=?')->execute([$qid,$cid]);$pts=(int)$db->query('SELECT points FROM cds_olympia_questions WHERE id='.$db->quote($qid))->fetchColumn();$ins=$db->prepare('INSERT INTO cds_olympia_scores(week_id,question_id,class_id,class_name,student_id,student_name,points,marked_by) VALUES(?,?,?,?,?,?,?,?)');$class=olympia_class_map()[$cid]??[];foreach((array)($_POST['student_ids']??[]) as $sid)if(isset($students[$sid]))$ins->execute([$wid,$qid,$cid,(string)($class['name']??''),$sid,(string)$students[$sid]['name'],$pts,$userName]);$db->commit();flash('Đã ghi nhận học sinh trả lời đúng.','success');oly_go('play',$wid,$cid);}
 }catch(Throwable $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();flash($e->getMessage(),'danger');oly_go($admin?'manage':'play',$wid);}
}
$view=in_array($_GET['view']??'',['play','manage','ranking'],true)?$_GET['view']:'play';if(!$admin&&$view!=='play')$view='play';$weeks=olympia_weeks();$weekId=trim((string)($_GET['week']??''));if($weekId==='')$weekId=(string)($weeks[0]['id']??'');$week=olympia_week($weekId);$weekClasses=$week?olympia_week_class_ids($weekId):[];$questions=$week?olympia_questions($weekId):[];$allowed=olympia_allowed_class_ids();$classes=array_values(array_filter(olympia_classes(),fn($c)=>in_array((string)$c['id'],$weekClasses,true)&&($allowed===null||in_array((string)$c['id'],$allowed,true))));$classId=trim((string)($_GET['class']??''));if($classId===''&&$classes)$classId=(string)$classes[0]['id'];$students=$classId?olympia_students($classId):[];
$marks=[];if($week&&$classId){$s=olympia_db()->prepare('SELECT question_id,student_id FROM cds_olympia_scores WHERE week_id=? AND class_id=?');$s->execute([$weekId,$classId]);foreach($s as $r)$marks[(string)$r['question_id']][]=(string)$r['student_id'];}
$rank=[];if($admin&&$view==='ranking'){$where=$weekId?'WHERE week_id='.olympia_db()->quote($weekId):'';$rank=olympia_db()->query("SELECT class_name,student_name,SUM(points) points,COUNT(*) correct FROM cds_olympia_scores $where GROUP BY class_id,student_id,class_name,student_name ORDER BY points DESC,student_name")->fetchAll();}
