e="student_ids[]" value="<?=e($s['id'])?>" <?=in_array((string)$s['id'],$marks[(string)$q['id']]??[],true)?'checked':''?>> <?=e($s['name'])?></label><?php endforeach?></div><div class="mt-3"><button class="btn btn-primary"><i class="bi bi-check2-circle"></i> Lưu câu này</button></div></form><?php endforeach;endif?><?php endif?></div></main></body></html>
